mapper.select:
/* isry.itgcm.casemng.caseunity.SrvcGrPvsnPlanMapper.selectSrvcGrPvsnPlanList(서비스집단제공계획목록조회) */ SELECT COUNT(*) OVER() AS TOT_CNT --공통추가 , T1.SRVC_PVSN_PLAN_NO AS SRVC_PVSN_PLAN_NO -- 서비스제공계획번호 , T1.RESRCE_NO AS RESRCE_NO -- 자원번호 , T1.RESRCE_NM AS RESRCE_NM -- 자원명 , T1.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T1.SRVC_GOAL_TTL_NM AS SRVC_EXCN_BIZ_NM -- 서비스실행사업명 , NVL((SELECT INST_NM FROM SAA000 WHERE INST_NO = T1.RSFR_INST_NO), (SELECT INST_NM FROM SDA600 WHERE INST_NO = T1.RSFR_INST_NO)) AS RSFR_INST_NM -- 자원제공주체명 , T1.PLAN_FNDNG_YMD AS PLAN_FNDNG_YMD -- 계획수립일자 , T1.PVSN_RESRCE_PRIR_RANK AS PVSN_RESRCE_PRIR_RANK -- 제공자원우선순위 , T1.PVSN_PRNMNT_BGNG_YMD AS PVSN_PRNMNT_BGNG_YMD -- 제공예정시작일자 , T1.PVSN_PRNMNT_END_YMD AS PVSN_PRNMNT_END_YMD -- 제공예정종료일자 , T1.PVSN_PRNMNT_BGNG_HR AS PVSN_PRNMNT_BGNG_HR -- 제공예정시작시간 , T1.PVSN_PRNMNT_END_HR AS PVSN_PRNMNT_END_HR -- 제공예정종료시간 , T1.PIC_NO AS PIC_NO -- 담당자번호 , (SELECT C##RG.DEC_B64(FLNM_ENCPT) FROM SCA100 WHERE ENFSN_NO = T1.PIC_NO) AS PIC_NM -- 담당자명 , CASE WHEN T1.TRPR_CNT > 1 THEN C##RG.DEC_B64(T1.TRPR_NM_ENCPT) || ' 외 ' || T1.CNT || '명' ELSE C##RG.DEC_B64(T1.TRPR_NM_ENCPT) END AS TRPR_CNT --대상자 FROM ( SELECT T2.SRVC_PVSN_PLAN_NO AS SRVC_PVSN_PLAN_NO -- 서비스제공계획번호 , T2.RESRCE_NO AS RESRCE_NO -- 자원번호 , T3.PVSN_RESRCE_NM AS RESRCE_NM -- 자원명 , T2.SRVC_GOAL_TTL_NM , T3.SRVC_TYPE_SE_CD AS SRVC_TYPE_SE_CD -- 서비스유형구분코드 , T3.RSFR_INST_NO AS RSFR_INST_NO -- 자원제공주체번호 , T2.PLAN_FNDNG_YMD AS PLAN_FNDNG_YMD -- 계획수립일자 , T2.PVSN_RESRCE_PRIR_RANK AS PVSN_RESRCE_PRIR_RANK -- 제공자원우선순위 , T2.PVSN_PRNMNT_BGNG_YMD AS PVSN_PRNMNT_BGNG_YMD -- 제공예정시작일자 , T2.PVSN_PRNMNT_END_YMD AS PVSN_PRNMNT_END_YMD -- 제공예정종료일자 , T2.PVSN_PRNMNT_BGNG_HR AS PVSN_PRNMNT_BGNG_HR -- 제공예정시작시간 , T2.PVSN_PRNMNT_END_HR AS PVSN_PRNMNT_END_HR -- 제공예정종료시간 , T2.PIC_NO AS PIC_NO -- 담당자번호 , T2.TKCG_INST_NO --담당기관번호 , T2.SRVC_EXCN_BIZ_NO AS SEB300_SRVC_EXCN_BIZ_NO , T3.SRVC_EXCN_BIZ_NO AS SDA100_SRVC_EXCN_BIZ_NO , X.TRPR_CNT , X.TRPR_NM_ENCPT , X.CNT FROM SEB300 T2 JOIN SDA100 T3 ON T2.RESRCE_NO = T3.RESRCE_NO LEFT JOIN ( SELECT A.SRVC_PVSN_PLAN_NO , COUNT(A.CASE_MNG_NO) AS TRPR_CNT , COUNT(A.CASE_MNG_NO) -1 AS CNT , MAX(C.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT FROM SEB310 A LEFT JOIN SEB100 B ON A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO LEFT JOIN SEA200 C ON B.TRPR_INFO_NO = C.TRPR_INFO_NO
WHERE 1=1 AND A.DEL_YN != 'Y'
GROUP BY A.SRVC_PVSN_PLAN_NO ) X ON T2.SRVC_PVSN_PLAN_NO = X.SRVC_PVSN_PLAN_NO
WHERE 1=1
AND T2.PLAN_FNDNG_YMD BETWEEN #{PLAN_FNDNG_BGNG_YMD} AND #{PLAN_FNDNG_END_YMD}
AND T3.PVSN_RESRCE_NM LIKE '%'||#{PVSN_RESRCE_NM}||'%'
AND T3.SRVC_TYPE_SE_CD = #{SRVC_TYPE_SE_CD}
AND T2.SRVC_GOAL_TTL_NM LIKE '%'||#{SRVC_EXCN_BIZ_NM}||'%'
AND T2.DEL_YN != 'Y' AND T2.SRVC_GR_PVSN_YN = 'Y' AND T3.USE_YN = 'Y'
ORDER BY T2.PLAN_FNDNG_YMD DESC, T2.SRVC_PVSN_PLAN_NO DESC ) T1 WHERE 1 = 1
